        0
      ) * fc.fund_cost_rate / 365
    + coalesce(co.ks_long_fee,0)
    - coalesce(tc.long_trade_amount,0) * 0.0000641
    - coalesce(cas.cust_total_fee,0),
    0
) AS Curr_Rev,


  --当日计提创收
    0 as Opt_Npv_Curr_Rev,  --当日期权NPV计提创收
